import java.util.LinkedList;
import java.util.Queue;

public class Main {
    public static void main(String[] args) {
        Queue<String> line = new LinkedList<>();
        line.offer("Ana");
        line.offer("Ben");
        line.offer("Cy");
        String served = line.poll();
        line.offer("Dee");
        System.out.println("Served " + served + ", waiting: " + line);
    }
}
